    fn release_sources(&self, sources: Vec<SenderSource>) -> usize {
        sources
            .iter()
            .map(|source| match source {
                SenderSource::Remote { batches, .. } => {
                    release_leases(self.executor.as_ref(), batches)
                }
                _ => 0,
            })
            .sum()
    }

